{"command": "cd ~/repo-b && cat > www/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Shared shopping list</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; max-width: 40rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.4; }
  h1 { font-size: 1.4rem; margin-bottom: 1rem; }
  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
  label { align-self: center; font-weight: 600; }
  #item { flex: 1; font-size: 1rem; padding: .5rem .6rem; border: 1px solid #8888; border-radius: .4rem; }
  button { font-size: 1rem; padding: .5rem .9rem; border: 1px solid #8888; border-radius: .4rem; cursor: pointer; background: #4a7; color: #fff; }
  button:disabled { opacity: .6; cursor: default; }
  ul { list-style: none; padding: 0; margin: 0; }
  li { display: flex; align-items: center; gap: .6rem; padding: .55rem .2rem; border-bottom: 1px solid #8883; }
  li label { font-weight: 400; flex: 1; cursor: pointer; word-break: break-word; }
  li.bought label { text-decoration: line-through; opacity: .55; }
  li input[type=checkbox] { width: 1.15rem; height: 1.15rem; cursor: pointer; }
  .del { background: none; color: #c44; border: none; padding: .1rem .4rem; font-size: 1.1rem; }
  #status { font-size: .8rem; opacity: .65; margin-top: 1rem; min-height: 1.2em; }
  .empty { opacity: .55; font-style: italic; padding: .7rem .2rem; }
</style>
</head>
<body>
<h1>Shared shopping list</h1>
<form id="add-form" autocomplete="off">
  <label for="item">Item</label>
  <input id="item" name="item" type="text" placeholder="e.g. milk" required maxlength="200">
  <button id="add-btn" type="submit">Add</button>
</form>
<ul id="list" aria-live="polite"></ul>
<div id="status" role="status"></div>

<script>
(() => {
  "use strict";
  const API = "/api/items";
  const POLL_MS = 1000;          // normal reconciliation poll (well under 5s)
  const LONGPoll_MS = 25000;     // server long-poll budget
  const listEl = document.getElementById("list");
  const statusEl = document.getElementById("status");
  const formEl = document.getElementById("add-form");
  const inputEl = document.getElementById("item");
  const addBtn = document.getElementById("add-btn");

  let version = null;            // last known server version
  let items = [];                // last known items
  let rendered = new Map();      // id -> {li, name, bought} for cheap diffing
  const pending = new Map();     // id -> {bought: bool} local optimistic intent
  let busy = false;

  const setStatus = (t) => { statusEl.textContent = t || ""; };

  function normalizeList(data) {
    const arr = Array.isArray(data) ? data : (data && Array.isArray(data.items)) ? data.items : [];
    const v = (!Array.isArray(data) && data && typeof data.version === "number") ? data.version
            : (!Array.isArray(data) && data && typeof data.version === "string") ? Number(data.version) : null;
    return {
      items: arr.map((it) => ({
        id: String(it.id),
        name: String(it.name ?? ""),
        bought: !!(it.bought ?? it.done ?? it.checked),
      })),
      version: Number.isFinite(v) ? v : null,
    };
  }

  function applyPending(list) {
    return list.map((it) => pending.has(it.id) ? { ...it, bought: pending.get(it.id).bought } : it);
  }

  function render() {
    const view = applyPending(items).sort((a, b) => (a.bought === b.bought ? 0 : a.bought ? 1 : -1));
    const seen = new Set();
    let prev = null;
    for (const it of view) {
      seen.add(it.id);
      let r = rendered.get(it.id);
      if (!r) {
        const li = document.createElement("li");
        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.setAttribute("aria-label", "Bought: " + it.name);
        cb.addEventListener("change", () => toggle(it.id, cb.checked, cb));
        const lab = document.createElement("label");
        const text = document.createTextNode(it.name); // text node: no HTML injection
        lab.appendChild(text);
        const del = document.createElement("button");
        del.type = "button"; del.className = "del"; del.title = "Remove";
        del.setAttribute("aria-label", "Remove " + it.name);
        del.textContent = "\u00d7";
        del.addEventListener("click", () => remove(it.id));
        li.append(cb, lab, del);
        r = { li, cb, lab, name: it.name, bought: null };
        rendered.set(it.id, r);
      }
      if (r.name !== it.name) {
        r.name = it.name;
        r.lab.lastChild.nodeValue = it.name;
        r.cb.setAttribute("aria-label", "Bought: " + it.name);
        r.li.querySelector(".del").setAttribute("aria-label", "Remove " + it.name);
      }
      if (r.bought !== it.bought) { r.bought = it.bought; r.cb.checked = it.bought; r.li.classList.toggle("bought", it.bought); }
      const target = prev ? prev.nextSibling : listEl.firstChild;
      if (target !== r.li) listEl.insertBefore(r.li, target);
      prev = r.li;
    }
    for (const [id, r] of rendered) if (!seen.has(id)) { r.li.remove(); rendered.delete(id); }
    let empty = listEl.querySelector(".empty");
    if (!view.length) {
      if (!empty) { empty = document.createElement("li"); empty.className = "empty"; empty.textContent = "Nothing on the list yet."; listEl.appendChild(empty); }
    } else if (empty) empty.remove();
  }

  async function fetchJSON(url, opts) {
    const res = await fetch(url, { cache: "no-store", headers: { "Accept": "application/json" }, ...opts });
    let data = null;
    if (res.status !== 204) { try { data = await res.json(); } catch (e) { data = null; } }
    if (!res.ok) throw new Error("HTTP " + res.status);
    return data;
  }

  async function refresh(opts = {}) {
    const useSince = version !== null && opts.longPoll !== false;
    const url = useSince ? API + "?since=" + encodeURIComponent(version) : API;
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), opts.timeout || (useSince ? LONGPoll_MS + 5000 : 5000));
    try {
      const data = await fetchJSON(url, { signal: ctrl.signal, headers: { "Accept": "application/json" } });
      if (Array.isArray(data) && useSince) return; // server ignored since and we already have data
      const norm = normalizeList(data);
      items = norm.items;
      if (norm.version !== null) version = norm.version;
      // drop optimistic intents confirmed by the server
      for (const it of items) if (pending.has(it.id) && pending.get(it.id).bought === it.bought) pending.delete(it.id);
      render();
      setStatus("Synced " + new Date().toLocaleTimeString());
    } catch (e) {
      setStatus("Offline or server unreachable - retrying…");
    } finally { clearTimeout(t); }
  }

  async function loop() {
    for (;;) {
      if (!busy) await refresh({ longPoll: true });
      await new Promise((r) => setTimeout(r, POLL_MS));
    }
  }

  async function toggle(id, bought, cb) {
    pending.set(id, { bought });
    items = items.map((it) => (it.id === id ? { ...it, bought } : it));
    render();
    try {
      await fetchJSON(API + "/" + encodeURIComponent(id), {
        method: "PATCH",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify({ bought }),
      });
      await refresh({ longPoll: false });
    } catch (e) {
      pending.delete(id);
      setStatus("Could not save that change - retrying…");
      await refresh({ longPoll: false });
    }
  }

  async function remove(id) {
    const prev = items;
    items = items.filter((it) => it.id !== id);
    pending.delete(id);
    render();
    try {
      await fetchJSON(API + "/" + encodeURIComponent(id), { method: "DELETE" });
      await refresh({ longPoll: false });
    } catch (e) {
      items = prev;
      render();
      setStatus("Could not remove that item.");
    }
  }

  formEl.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    const name = inputEl.value.trim();
    if (!name) return;
    inputEl.value = "";
    addBtn.disabled = true; busy = true;
    try {
      await fetchJSON(API, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify({ name }),
      });
    } catch (e) {
      setStatus("Could not add the item - is the server up?");
      if (!inputEl.value) inputEl.value = name;
    } finally {
      busy = false; addBtn.disabled = false; inputEl.focus();
      await refresh({ longPoll: false });
    }
  });

  // Re-sync promptly when the tab regains focus / visibility.
  window.addEventListener("focus", () => refresh({ longPoll: false }));
  document.addEventListener("visibilitychange", () => { if (!document.hidden) refresh({ longPoll: false }); });

  render();
  refresh({ longPoll: false }).then(loop);
})();
</script>
</body>
</html>
